function Dot({tone='green'}){return <span className={'admin-dot '+tone}/>;}
function Drawer({title,onClose,children}){return <div className="admin-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><aside className="admin-drawer" role="dialog" aria-modal="true" aria-label={title}><header className="admin-drawer-head"><h2>{title}</h2><button onClick={onClose} aria-label="Закрыть">×</button></header>{children}</aside></div>;}
function Modal({title,onClose,children}){return <div className="admin-modal-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section className="admin-modal"><header><h3>{title}</h3><button onClick={onClose}>×</button></header>{children}</section></div>;}
function Tabs({items,value,onChange}){return <nav className="admin-tabs">{items.map(x=><button key={x[0]} className={value===x[0]?'active':''} onClick={()=>onChange(x[0])}>{x[1]}</button>)}</nav>;}
function Toolbar({search,setSearch,children}){return <div className="admin-toolbar"><label className="admin-search">⌕<input placeholder="Поиск" value={search} onChange={e=>setSearch(e.target.value)}/></label>{children}</div>;}
function Empty({text='Данных пока нет'}){return <div className="admin-empty">{text}</div>;}

