 return <main className="admin-main"><h1>{localStorage.getItem('giik.system.name')||'ИИ-тренажёр 112'} · Администратор</h1><p className="admin-subtitle">Сводка по объектам приложения</p><div className="admin-kpis">{[['users','Пользователи',model.users.length],['scenarios','Учебные сценарии',model.scenarios.length],['cards','Учебные карточки',model.cards.length],['trainings','Тренировки',model.trainings.length],['monitoring','Предупреждения',warnings]].map(([k,l,v])=><button key={k} onClick={()=>onOpen(k)}><span>{l}</span><strong>{v}</strong><i>›</i></button>)}</div><div className="admin-dashboard-grid"><section className="admin-panel admin-system"><header>Состояние системы</header><table><thead><tr><th>Компонент</th><th>Состояние</th><th>Последняя проверка</th><th>Метрика</th></tr></thead><tbody>{[['Интерфейс','Открыт','Страница загружена'],['ИИ-модуль','Не проверен','Проверить в мониторинге'],['Учебные данные',data.error?'Ошибка':data.loading?'Загрузка':'Данные получены',`${data.sessions.length} работ`],['Карточки','Локальные данные',`${model.cards.length} шт.`],['Сценарии','Данные получены',`${model.scenarios.length} шт.`]].map(([a,b,c])=><tr key={a}><td>{a}</td><td><Dot tone={b==='Ошибка'?'red':b==='Не проверен'||b==='Загрузка'?'gray':'green'}/>{b}</td><td>{a==='Учебные данные'&&!data.error&&!data.loading?'При загрузке страницы':'—'}</td><td>{c}</td></tr>)}</tbody></table></section><section className="admin-panel admin-llm-summary"><header>ИИ-сервисы</header><div><b>Внешний ИИ</b><span><Dot tone="gray"/>Не проверен</span><small>Проверка выполняется в мониторинге</small></div><div><b>Маршрутизация запросов</b><span>Основная модель</span><small>Ключ задаётся локально</small></div><button onClick={()=>onOpen('monitoring')}>Открыть мониторинг</button></section><section className="admin-panel admin-events-panel"><header>Последние системные события</header>{events.length?events.map(s=><p key={s.id}><span>{fmt(s.updated_at||s.created_at)}</span><b>{s.student}</b><em>{s.training?.title||s.title} · {statusLabel[s.status]||s.status}</em><Dot tone="blue"/></p>):<p>Учебных событий пока нет.</p>}</section><section className="admin-panel admin-warning-panel"><header>Системные предупреждения</header>{warnings?<><article><Dot tone="orange"/><div><b>Есть элементы, требующие внимания</b><p>{model.cards.filter(c=>c.status!=='approved').length} карточек ещё не утверждено.</p></div></article>{data.error&&<article><Dot tone="red"/><div><b>Ошибка получения данных</b><p>{data.error}</p></div></article>}</>:<article><Dot/><div><b>Предупреждений нет</b><p>В загруженных данных нет предупреждений. Проверка ИИ и голоса доступна в мониторинге.</p></div></article>}</section></div></main>;
